import{_ as e,o as t,c as l,ag as i}from"./chunks/framework.CvZZEx4j.js";const p=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),r={name:"guide/getting-started.md"};function o(s,a,n,d,h,g){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>在使用 Galgame 界面插件之前，你需要准备：</p><ol><li><strong>SillyTavern</strong>（酒馆）—— <a href="https://sillytavern.app/" target="_blank" rel="noreferrer">官方网站</a></li><li><strong>酒馆助手插件</strong>（Tavern Helper）—— <a href="https://n0vi028.github.io/JS-Slash-Runner-Doc/" target="_blank" rel="noreferrer">安装说明</a></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>确保酒馆助手已正确安装并启用，Galgame 界面插件依赖酒馆助手提供的接口运行。</p></div><h2 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to &quot;安装插件&quot;">​</a></h2><h3 id="方式一-导入脚本-json-推荐" tabindex="-1">方式一：导入脚本 JSON（推荐） <a class="header-anchor" href="#方式一-导入脚本-json-推荐" aria-label="Permalink to &quot;方式一：导入脚本 JSON（推荐）&quot;">​</a></h3><ol><li>下载插件脚本 JSON 文件</li><li>在 SillyTavern 中，进入 <strong>扩展</strong> → <strong>酒馆助手</strong> → <strong>脚本管理</strong></li><li>点击 <strong>导入脚本</strong>，选择下载的 JSON 文件</li><li>导入成功后，脚本列表中会出现「galgame界面插件」</li></ol><h3 id="方式二-通过远程链接加载" tabindex="-1">方式二：通过远程链接加载 <a class="header-anchor" href="#方式二-通过远程链接加载" aria-label="Permalink to &quot;方式二：通过远程链接加载&quot;">​</a></h3><p>在酒馆助手的脚本管理中，新建一个脚本，内容填写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import &#39;https://gcore.jsdelivr.net/gh/bigmalove/galgame@v1.1/dist/数据库界面插件.dist.js&#39;</span></span></code></pre></div><h2 id="第一次启用" tabindex="-1">第一次启用 <a class="header-anchor" href="#第一次启用" aria-label="Permalink to &quot;第一次启用&quot;">​</a></h2><ol><li>打开一个角色卡的聊天界面</li><li>在聊天区域的右下角，你会看到一个 <strong>Galgame 按钮</strong>（🎮）</li><li>点击按钮即可 <strong>打开/关闭</strong> Galgame 覆盖层</li><li>发送消息后，AI 的回复将以 Galgame 格式展示</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 提示</p><p>首次使用时，建议先在设置面板中点击「注入世界书」，这样 AI 就会按照 Galgame 格式输出内容。</p></div><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><p>如果一切正常，你应该能看到：</p><ul><li>✅ 聊天区域出现半透明的 Galgame 覆盖层</li><li>✅ AI 的回复以对话框形式逐段展示</li><li>✅ 点击覆盖层或「下一步」按钮可推进对话</li></ul><div class="info custom-block"><p class="custom-block-title">🎯 我是角色卡作者</p><p>如果你想为自己的角色卡制作「开箱即用」的 Galgame 体验，请查看 <a href="/galgame/card-author/overview.html">角色卡作者接入指南</a>。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>了解一下 <a href="/galgame/guide/ui-overview.html">界面总览</a>，熟悉 Galgame 覆盖层的各个组成部分。</p>',20)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
